use std::collections::BTreeMap;impl Solution{pub fn get_skyline(b:Vec<Vec<i32>>)->Vec<Vec<i32>>{let mut e=vec![];for x in b{e.push((x[0],-x[2]));e.push((x[1],x[2]));}e.sort();let mut h=BTreeMap::new();h.insert(0,1);let mut o=vec![];let mut prev=0;for(x,v)in e{if v<0{*h.entry(-v).or_insert(0)+=1}else if let Some(c)=h.get_mut(&v){*c-=1;if *c==0{h.remove(&v);}}let cur=*h.keys().next_back().unwrap();if cur!=prev{o.push(vec![x,cur]);prev=cur;}}o}}
